class Flow:
    def __init__(self, id, period, deadline, source, destination, route):
        self.id = id
        self.period = period
        self.deadline = deadline
        self.source = source
        self.destination = destination
        self.route = route

def create_individual_flows(application_flows):
    individual_flows = []
    flow_id_counter = 1
    for app_flow in application_flows:
        for route in app_flow.routes:
            individual_flows.append(Flow(flow_id_counter, app_flow.period, app_flow.deadline, app_flow.source, app_flow.destination, route))
            flow_id_counter += 1
    return individual_flows

class Flow:
    # ... (previous attributes)
    def __init__(self, id, period, deadline, source, destination, route, priority_rank):
        # ...
        self.priority_rank = priority_rank # 1 for highest, N for lowest

def get_higher_priority_flows(flow_i, all_flows):
    hp_flows = []
    for other_flow in all_flows:
        if other_flow.priority_rank < flow_i.priority_rank:
            hp_flows.append(other_flow)
    return hp_flows

def is_flow_set_schedulable(flow_set, scheduling_algorithm, num_channels):
    for flow_i in flow_set:
        # This function would be the core of the analysis, calculating WCRT
        worst_case_delay_i = calculate_worst_case_end_to_end_delay(flow_i, flow_set, scheduling_algorithm, num_channels)
        if worst_case_delay_i > flow_i.deadline:
            return False # A deadline is missed
    return True # All deadlines are met

def check_schedulability_with_wcrt(flow_set):
    for flow_i in flow_set:
        # Assume R_channel_conflict_i is already computed
        if flow_i.R_channel_conflict > flow_i.deadline:
            return False # Not schedulable
    return True # Schedulable

def do_transmissions_conflict(tx_k_sender, tx_k_receiver, tx_i_sender, tx_i_receiver):
    if tx_k_sender == tx_i_sender or \
       tx_k_sender == tx_i_receiver or \
       tx_k_receiver == tx_i_sender or \
       tx_k_receiver == tx_i_receiver:
        return True
    return False

def do_flows_conflict(flow_k, flow_i):
    # This would involve checking all transmission pairs along their routes
    for tx_k in flow_k.transmissions:
        for tx_i in flow_i.transmissions:
            if do_transmissions_conflict(tx_k.sender, tx_k.receiver, tx_i.sender, tx_i.receiver):
                return True
    return False

def calculate_interference_no_carry_in(t, flow_i, flow_k):
    workload = calculate_workload_no_carry_in(t, flow_i)
    max_interference_duration = t - flow_k.num_transmissions + 1
    return min(workload, max_interference_duration)

def calculate_interference_carry_in(t, flow_i, flow_k, mu_i):
    workload = calculate_workload_carry_in(t, flow_i, mu_i)
    max_interference_duration = t - flow_k.num_transmissions + 1
    return min(workload, max_interference_duration)

def calculate_delta_k_i(flow_k, flow_i, mcps_k_i):
    Q_k_i = calculate_Q_k_i(flow_k, flow_i)

    sum_excess_conflicts = 0
    for mcp in mcps_k_i:
        delta_j_k_i = calculate_delta_j_k_i(mcp, flow_i.route) # Assuming flow_i.route is available
        if delta_j_k_i >= 4:
            sum_excess_conflicts += (delta_j_k_i - 3)

    return Q_k_i - sum_excess_conflicts

def calculate_R_channel_k(flow_k, hp_flows, num_channels, deadline_k):
    x = flow_k.num_transmissions # Initial guess
    while True:
        omega_k_x = calculate_total_interference_channel_contention(x, flow_k, hp_flows, num_channels)
        x_new = (omega_k_x // num_channels) + flow_k.num_transmissions

        if x_new == x:
            return x # Fixed point found
        if x_new > deadline_k:
            return float('inf') # Unschedulable
        x = x_new

def calculate_R_channel_conflict_k(flow_k, hp_flows, R_channel_k, deadline_k):
    y = R_channel_k # Initial guess
    while True:
        theta_k_y = calculate_total_conflict_delay(y, flow_k, hp_flows)
        y_new = R_channel_k + theta_k_y

        if y_new == y:
            return y # Fixed point found
        if y_new > deadline_k:
            return float('inf') # Unschedulable
        y = y_new
